#!/usr/bin/env bash
# PreToolUse (Edit|Write): refuse edits to generated or vendored files.
#   node_modules/  installed packages (67js is pinned; change it in package.json, not in place)
#   dist/          build output, regenerated by `npm run build`
#   public/legacy/ the original prototype, kept as it was
f=$(jq -r '.tool_input.file_path // empty')
case "$f" in
  */node_modules/*|*/dist/*|*/public/legacy/*)
    jq -n --arg f "$f" '{hookSpecificOutput:{hookEventName:"PreToolUse",permissionDecision:"deny",permissionDecisionReason:("\($f) is generated or vendored; edit the source under src/ (or package.json) instead.")}}'
    ;;
esac
exit 0
